"""Triton implementation of aten::upsample_trilinear3d_backward.

Backward (adjoint) of trilinear 3D interpolation.

The adjoint is separable: A = A_d (x) A_h (x) A_w, so it is applied as two
cheap passes (the fused d+h axis pass, then the w axis) instead of one 3-D
stencil:

  t2[n,c,id,ih,ow]  = sum_kd sum_kh W_d(od -> id) W_h(oh -> ih) * grad_output
  out[n,c,id,ih,iw] = sum_kw W_w(ow -> iw) * t2[n,c,id,ih,ow]

Per-axis tap count is K = ceil(2/scale) (4 for an exact 2x upsample without
align_corners, 5 with align_corners), i.e. the work grows linearly rather than
cubically in K.  The first pass reads fully coalesced rows; the w pass, whose
output plane is the smallest, is the only one that reads the output-w axis with
a stride.  Weights and the max(...,0) clamp reproduce ATen's
area_pixel_compute_source_index exactly; all accumulation is fp32.

Fallback: output-driven atomic scatter, used only when a per-axis scale
degenerates to zero (align_corners with a spatial size of 1).
"""

import math

import torch
import triton
import triton.language as tl


# ---------------------------------------------------------------------------
# pass 1: fused d+h adjoint,  (N*C, O_d, O_h, O_w) -> (N*C, I_d, I_h, O_w)
# ---------------------------------------------------------------------------
@triton.jit
def _adjoint_dh(
    src,
    dst,
    O_d,
    I_d,
    O_h,
    I_h,
    O_w,
    P,
    s_d,
    b_d,
    r_d,
    s_h,
    b_h,
    r_h,
    KD: tl.constexpr,
    KH: tl.constexpr,
    BH: tl.constexpr,
    BW: tl.constexpr,
):
    pid_w = tl.program_id(0)
    pid_h = tl.program_id(1)
    pid_z = tl.program_id(2)

    id = pid_z % I_d
    nc = pid_z // I_d

    ih = pid_h * BH + tl.arange(0, BH)
    ow = pid_w * BW + tl.arange(0, BW)
    mask = (ih < I_h)[:, None] & (ow < O_w)[None, :]

    src_b = nc.to(tl.int64) * O_d.to(tl.int64) * P.to(tl.int64)
    dst_b = pid_z.to(tl.int64) * (I_h.to(tl.int64) * O_w)

    ld = tl.maximum(
        (-tl.floor(-((id.to(tl.float32) - 1.0 - b_d) * r_d))).to(tl.int32), 0
    )
    lh = tl.maximum(
        (-tl.floor(-((ih.to(tl.float32) - 1.0 - b_h) * r_h))).to(tl.int32), 0
    )

    # Row-major tap walk: the (row, col) address of the first tap of a row is a
    # single pointer tensor shared by all depth taps, the per-row bound mask is
    # hoisted out of the depth loop, and a depth tap is one scalar displacement
    # (with the depth index clamped for the address and its weight zeroed).
    hw = lh[:, None] * O_w + ow[None, :]
    out_off = ih[:, None] * O_w + ow[None, :]
    p_row = src + (src_b + hw.to(tl.int64))

    acc = tl.zeros((BH, BW), dtype=tl.float32)
    for kh in tl.static_range(KH):
        ohv = lh + kh
        srh = tl.maximum(s_h * ohv.to(tl.float32) + b_h, 0.0)
        j0h = tl.floor(srh)
        lmh = srh - j0h
        j0hi = j0h.to(tl.int32)
        wh = (j0hi == ih).to(tl.float32) * (1.0 - lmh) + (
            tl.minimum(j0hi + 1, I_h - 1) == ih
        ).to(tl.float32) * lmh
        mkh = mask & (ohv < O_h)[:, None]
        for kd in tl.static_range(KD):
            odv = ld + kd
            srd = tl.maximum(s_d * odv.to(tl.float32) + b_d, 0.0)
            j0d = tl.floor(srd)
            lmd = srd - j0d
            j0di = j0d.to(tl.int32)
            wd = (
                (j0di == id).to(tl.float32) * (1.0 - lmd)
                + (tl.minimum(j0di + 1, I_d - 1) == id).to(tl.float32) * lmd
            ) * (odv < O_d).to(tl.float32)
            off = tl.minimum(odv, O_d - 1) * P + kh * O_w
            g = tl.load(p_row + off, mask=mkh, other=0.0)
            acc += g * (wd * wh)[:, None]
    tl.store(dst + dst_b + out_off, acc, mask=mask)


# ---------------------------------------------------------------------------
# pass 3: w-axis adjoint,  (N*C*I_d*I_h, O_w) -> (N*C*I_d*I_h, I_w)  (+cast)
# ---------------------------------------------------------------------------
@triton.jit
def _adjoint_w(
    src,
    dst,
    I_h,
    O_w,
    I_w,
    s_w,
    b_w,
    r_w,
    KW: tl.constexpr,
    BH: tl.constexpr,
    BW: tl.constexpr,
):
    pid_w = tl.program_id(0)
    pid_h = tl.program_id(1)
    pid_z = tl.program_id(2)

    ih = pid_h * BH + tl.arange(0, BH)
    iw = pid_w * BW + tl.arange(0, BW)
    mask = (ih < I_h)[:, None] & (iw < I_w)[None, :]

    src_b = pid_z.to(tl.int64) * (I_h.to(tl.int64) * O_w)
    dst_b = pid_z.to(tl.int64) * (I_h.to(tl.int64) * I_w)

    lw = tl.maximum(
        (-tl.floor(-((iw.to(tl.float32) - 1.0 - b_w) * r_w))).to(tl.int32), 0
    )

    row_in = ih[:, None] * O_w
    row_out = ih[:, None] * I_w

    acc = tl.zeros((BH, BW), dtype=tl.float32)
    for kw in tl.static_range(KW):
        owv = lw + kw
        sr = tl.maximum(s_w * owv.to(tl.float32) + b_w, 0.0)
        j0 = tl.floor(sr)
        lam = sr - j0
        j0i = j0.to(tl.int32)
        w = (j0i == iw).to(tl.float32) * (1.0 - lam) + (
            tl.minimum(j0i + 1, I_w - 1) == iw
        ).to(tl.float32) * lam
        g = tl.load(
            src + src_b + row_in + owv[None, :],
            mask=mask & (owv < O_w)[None, :],
            other=0.0,
        )
        acc += g * w[None, :]
    tl.store(
        dst + dst_b + row_out + iw[None, :], acc.to(dst.dtype.element_ty), mask=mask
    )


# ---------------------------------------------------------------------------
# fallback: output-driven atomic scatter
# ---------------------------------------------------------------------------
@triton.jit
def _trilinear3d_backward_scatter(
    go_ptr,
    gi_ptr,
    D_out,
    H_out,
    W_out,
    D_in,
    H_in,
    W_in,
    s_d,
    s_h,
    s_w,
    ALIGN: tl.constexpr,
    BH: tl.constexpr,
    BW: tl.constexpr,
):
    pid_w = tl.program_id(0)
    pid_h = tl.program_id(1)
    pid_z = tl.program_id(2)

    od = pid_z % D_out
    nc = pid_z // D_out

    ow = pid_w * BW + tl.arange(0, BW)
    oh = pid_h * BH + tl.arange(0, BH)
    mw = ow < W_out
    mh = oh < H_out
    mask = mh[:, None] & mw[None, :]

    owf = ow.to(tl.float32)
    ohf = oh.to(tl.float32)
    odf = od.to(tl.float32)

    if ALIGN:
        sw = s_w * owf
        sh = s_h * ohf
        sd = s_d * odf
    else:
        sw = tl.maximum(s_w * (owf + 0.5) - 0.5, 0.0)
        sh = tl.maximum(s_h * (ohf + 0.5) - 0.5, 0.0)
        sd = tl.maximum(s_d * (odf + 0.5) - 0.5, 0.0)

    w0f = tl.floor(sw)
    h0f = tl.floor(sh)
    d0f = tl.floor(sd)
    lw = sw - w0f
    lh = sh - h0f
    ld = sd - d0f

    w0 = w0f.to(tl.int32)
    h0 = h0f.to(tl.int32)
    d0 = d0f.to(tl.int32)
    w1 = tl.minimum(w0 + 1, W_in - 1)
    h1 = tl.minimum(h0 + 1, H_in - 1)
    d1 = tl.minimum(d0 + 1, D_in - 1)

    go_off = (
        (nc.to(tl.int64) * D_out + od) * (H_out * W_out)
        + oh[:, None] * W_out
        + ow[None, :]
    )
    g = tl.load(go_ptr + go_off, mask=mask, other=0.0).to(tl.float32)

    plane_in = H_in * W_in
    gi_base = nc.to(tl.int64) * (D_in.to(tl.int64) * plane_in)
    dbase0 = gi_base + d0.to(tl.int64) * plane_in
    dbase1 = gi_base + d1.to(tl.int64) * plane_in

    hw00 = h0[:, None] * W_in + w0[None, :]
    hw01 = h0[:, None] * W_in + w1[None, :]
    hw10 = h1[:, None] * W_in + w0[None, :]
    hw11 = h1[:, None] * W_in + w1[None, :]

    ww0 = (1.0 - lw)[None, :]
    ww1 = lw[None, :]
    wh0 = (1.0 - lh)[:, None]
    wh1 = lh[:, None]
    wd0 = 1.0 - ld
    wd1 = ld

    tl.atomic_add(
        gi_ptr + dbase0 + hw00, g * (wd0 * wh0 * ww0), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase0 + hw01, g * (wd0 * wh0 * ww1), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase0 + hw10, g * (wd0 * wh1 * ww0), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase0 + hw11, g * (wd0 * wh1 * ww1), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase1 + hw00, g * (wd1 * wh0 * ww0), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase1 + hw01, g * (wd1 * wh0 * ww1), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase1 + hw10, g * (wd1 * wh1 * ww0), mask=mask, sem="relaxed"
    )
    tl.atomic_add(
        gi_ptr + dbase1 + hw11, g * (wd1 * wh1 * ww1), mask=mask, sem="relaxed"
    )


@triton.jit
def _cast_kernel(src_ptr, dst_ptr, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    off = pid * BLOCK + tl.arange(0, BLOCK)
    m = off < n
    v = tl.load(src_ptr + off, mask=m)
    tl.store(dst_ptr + off, v.to(dst_ptr.dtype.element_ty), mask=m)


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------
def _axis_scale(in_size, out_size, align, scales):
    if align:
        return float(in_size - 1) / float(out_size - 1) if out_size > 1 else 0.0
    if scales is not None and float(scales) > 0:
        return float(1.0 / float(scales))
    return float(in_size) / float(out_size)


def _axis_params(in_size, out_size, align, scales):
    """(scale, offset, 1/scale, K) for one spatial axis.

    K is the number of grad_output indices that can contribute to a single
    grad_input index: a half-open window of length 2/scale holds at most
    ceil(2/scale) integers.
    """
    s = _axis_scale(in_size, out_size, align, scales)
    b = 0.0 if align else 0.5 * s - 0.5
    if s <= 0.0:
        return 0.0, b, 0.0, 0
    span = 2.0 / s
    k = int(math.floor(span))
    if span - k > 1e-6:
        k += 1
    return s, b, 1.0 / s, max(1, k)


def _tile(n_cols, max_block=512):
    # Two outputs per thread (the previous max_block=256 with BW=128 layout)
    # leaves the per-tap scalar bookkeeping - 64-bit address formation,
    # predicate save/restore, zero-fill movs - warp-uniform and therefore
    # unamortised; ~50% of the executed instruction stream is that
    # bookkeeping, so doubling the elements per thread halves its share.
    bw = min(128, triton.next_power_of_2(n_cols))
    bh = max(1, max_block // bw)
    return bh, bw


def upsample_trilinear3d_backward(
    grad_output,
    output_size,
    input_size,
    align_corners,
    scales_d=None,
    scales_h=None,
    scales_w=None,
):
    go = grad_output
    if not go.is_contiguous():
        go = go.contiguous()

    sizes = tuple(int(x) for x in input_size)
    N, C, D_in, H_in, W_in = sizes[-5], sizes[-4], sizes[-3], sizes[-2], sizes[-1]
    out3 = tuple(int(x) for x in output_size)
    D_out, H_out, W_out = out3[-3], out3[-2], out3[-1]
    dtype = go.dtype
    device = go.device

    if N * C * D_in * H_in * W_in == 0:
        return torch.empty(sizes, dtype=dtype, device=device)
    if D_out * H_out * W_out == 0 or go.numel() == 0:
        return torch.zeros(sizes, dtype=dtype, device=device)

    align = bool(align_corners)
    s_d, b_d, r_d, k_d = _axis_params(D_in, D_out, align, scales_d)
    s_h, b_h, r_h, k_h = _axis_params(H_in, H_out, align, scales_h)
    s_w, b_w, r_w, k_w = _axis_params(W_in, W_out, align, scales_w)

    NC = N * C
    int32_ok = (H_out * W_out) < (1 << 30) and N * C * D_in * H_in * W_in < (1 << 31)
    if k_d > 0 and k_h > 0 and k_w > 0 and max(k_d, k_h, k_w) <= 16 and int32_ok:
        # ---- separable adjoint: fused (d,h) pass, then the w pass ----
        P = H_out * W_out
        t2 = torch.empty((NC, D_in, H_in, W_out), dtype=torch.float32, device=device)
        out = torch.empty(sizes, dtype=dtype, device=device)

        bh, bw = _tile(W_out)
        grid = (triton.cdiv(W_out, bw), triton.cdiv(H_in, bh), NC * D_in)
        _adjoint_dh[grid](
            go,
            t2,
            D_out,
            D_in,
            H_out,
            H_in,
            W_out,
            P,
            s_d,
            b_d,
            r_d,
            s_h,
            b_h,
            r_h,
            KD=k_d,
            KH=k_h,
            BH=bh,
            BW=bw,
            num_warps=4,
        )

        bh, bw = _tile(W_in)
        grid = (triton.cdiv(W_in, bw), triton.cdiv(H_in, bh), NC * D_in)
        _adjoint_w[grid](
            t2,
            out,
            H_in,
            W_out,
            W_in,
            s_w,
            b_w,
            r_w,
            KW=k_w,
            BH=bh,
            BW=bw,
            num_warps=4,
        )
        return out

    # ---- fallback: atomic scatter ----
    acc = torch.zeros(sizes, dtype=torch.float32, device=device)
    BW = min(64, triton.next_power_of_2(W_out))
    BH = max(1, 256 // BW)
    grid = (triton.cdiv(W_out, BW), triton.cdiv(H_out, BH), N * C * D_out)
    _trilinear3d_backward_scatter[grid](
        go,
        acc,
        D_out,
        H_out,
        W_out,
        D_in,
        H_in,
        W_in,
        s_d,
        s_h,
        s_w,
        ALIGN=align,
        BH=BH,
        BW=BW,
        num_warps=4,
    )
    if dtype == torch.float32:
        return acc
    out = torch.empty(sizes, dtype=dtype, device=device)
    n = acc.numel()
    _cast_kernel[(triton.cdiv(n, 1024),)](acc, out, n, BLOCK=1024, num_warps=4)
    return out
